function loginUser(password, email, userId, onsuccess, onError) {
    var body = {};
    if (password === null) {
        body = {
            user_id: userId,
            email: email,
            vscode_version: "0.1.31"
        };
    }
    else {
        body = {
            email: email,
            password: password,
            vscode_version: "0.1.31"
        };
    }
    vscode.window.showInformationMessage("Logging in user please hold on...", { modal: false });
    api.post("/vs-code/auth/login", body)
        .then((reponse) => {
        justLoggedIn = true;
        const url = `/payment/get_user_info?id=${(0, projectUtils_1.getDataFromCache)((0, extension_1.getExtensionContext)(), projectUtils_1.APIKEY, "")}`;
        const headers = {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${reponse.data["access_token"]["access_token"]}`,
            // Add any other headers as needed
        };
        // Make the Axios request with headers
        api.get(url, {
            headers: headers
        })
            .then(response => {
            // Handle successful response
            var resp = response.data;
            if (resp["subscriber"]) {
                (0, projectUtils_1.saveDataToCache)((0, extension_1.getExtensionContext)(), projectUtils_1.ADDED_BILLING, "true");
            }
            else {
                (0, projectUtils_1.saveDataToCache)((0, extension_1.getExtensionContext)(), projectUtils_1.ADDED_BILLING, "false");
            }
            vscode.window.showInformationMessage("Login successsful, welcome to the Sixth 😊!!", { modal: false });
            onsuccess(reponse.data);
        })
            .catch(error => {
        });
    }).catch((error => {
        const error_type = error.response.data["detail"];
        if (error_type["required_action"] === "ADD_CARD") {
            vscode.window.showInformationMessage("Oops it seems you haven't added a valid cards yet , please add one to continue 😬", { modal: true });
        }
        else {
            vscode.window.showInformationMessage(error.response.data["detail"], { modal: true });
        }
        onError(error);
    }));
}
function generateRandom10Digits() {
    let randomNumber = '';
    for (let i = 0; i < 10; i++) {
        randomNumber += Math.floor(Math.random() * 10); // Generate a random digit (0-9)
    }
    return randomNumber;
}
